signature.css:
/* the story thread: one per view */
.thread {
  background: var(--accent-fill);
  color: var(--on-accent);
  padding: 0 .25em;
  border-radius: 4px;
}

/* specimen card and the don't example */
.ss-card { display: grid; gap: 10px; padding: 16px; border-radius: 12px; background: var(--page); border: 1px solid var(--divider); }
.ss-h { font-family: var(--font-display); font-size: 1.35rem; font-weight: 600; }
.ss-pink { color: var(--blush) !important; }
.ss-pink-btn { background: var(--blush); color: #fff; }
